"""
Environment configuration for UP4 Pipeline
Contains environment-specific settings for simulation vs real robot operation
"""

import numpy as np
from scipy.spatial.transform import Rotation as R


def get_pipeline_config():
    """
    Returns pipeline configuration dictionary containing:
    - Runtime flags (online, recalculate, etc.)
    - Experiment settings (object, environment, approach)
    - Heuristic settings (enabled heuristic names, subsample fraction)
    - System flags (moveit_flag)
    """
    return {
        "runtime": {
            "online": False,  # True/False - Run code online, or use last available data
            "recalculate_grasps": False,  # Recalculate grasps instead of loading
            "recalculate_placeposes": False,  # Recalculate place poses instead of loading
            "use_static_cam": True,  # Use static camera for data
            "reachability_flag": False,  # Use reachability map validation
            "moveit_flag": True,  # Use moveit for motion planning
            "chunk_size": 30,  # Batch size for motion planning calls (NOTE chunk size heavily depends on GPU, on strong GPU can set to 100+)
        },
        "experiment": {
            "object": "drill",  # pringles, mustard, cracker, drill, milk, muesli
            "run_number": "1",  # Run identifier
            "environment": "lower_shelf",  # dense, sparse, lower_shelf, superlow_shelf, bin
            "approach": "ours",  # ours, baseline1, baseline2, baseline3, baseline4
        },
        "heuristic": {
            "heuristic": None, #["dense_packing"],  # Supported: clearance, dense_packing
            "heuristic_subsample_fraction": 0.2,  # 1.0 is slow but accurate, lower is faster
        },
        "stability": {
            "mode": "probabilistic_mc",  # Stability analysis mode
            "n_mc_samples": 1000,  # Number of Monte Carlo samples
            "tau": 0.05,  # Stability threshold
            "com_method": "hybrid",  # Center of mass computation method
            "com_geo_scale": 0.5,  # Geometric scale for COM calculation
        },
    }

